import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 5

def design(feats):
    # Identify strong features (p < 0.01)
    strong = []
    for i in range(len(feats.ids)):
        if len(feats.x[:,i]) > 2:
            t_stat, p_val = stats.ttest_ind(feats.x[:,i][feats.y==1], feats.x[:,i][feats.y==0])
            if p_val < 0.01:
                strong.append(i)

    # Remove near-duplicates (correlation > 0.6)
    if len(strong) <= 1:
        to_remove = set()
    else:
        corr = np.corrcoef(feats.x[:, strong].T)
        to_remove = set()
        for i in range(len(strong)):
            for j in range(i+1, len(strong)):
                if abs(corr[i,j]) > 0.6:
                    to_remove.add(j)
    strong = [s for i, s in enumerate(strong) if i not in to_remove]

    # If we have too many strong features, just take the top ones by effect size
    if len(strong) > MAX_DRIVERS:
        effect_sizes = [abs(np.mean(feats.x[:,f][feats.y==1]) - np.mean(feats.x[:,f][feats.y==0])) for f in strong]
        strong = [strong[i] for i in np.argsort(effect_sizes)[::-1][:MAX_DRIVERS]]

    # Select drivers as top strong features
    drivers = [feats.ids[f] for f in strong[:MAX_DRIVERS]]

    # Build products from pairs of strong features (limit to 5 pairs max)
    products = []
    if len(strong) > 1:
        corr = np.corrcoef(feats.x[:, strong].T)
        pairs = []
        for i in range(len(strong)):
            for j in range(i+1, len(strong)):
                if abs(corr[i,j]) > 0.6:
                    pairs.append((i, j))
        # Take top 5 correlated pairs by correlation strength
        pairs.sort(key=lambda x: abs(corr[x[0],x[1]]), reverse=True)
        for i, j in pairs[:5]:
            products.append((feats.ids[strong[i]], feats.ids[strong[j]]))

    return Design(
        drivers=tuple(drivers),
        columns=feats.ids,
        products=tuple(products),
        loadings={}
    )
